CREATE TABLE wallets(id RAW(16) DEFAULT SYS_GUID() PRIMARY KEY, user_id RAW(16) NOT NULL REFERENCES users(id), currency VARCHAR2(3) NOT NULL, balance NUMBER(19,4) DEFAULT 0 NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE ledger_entries(id RAW(16) DEFAULT SYS_GUID() PRIMARY KEY, wallet_id RAW(16) NOT NULL REFERENCES wallets(id), entry_type VARCHAR2(10) NOT NULL, amount NUMBER(19,4) NOT NULL, currency VARCHAR2(3) NOT NULL, idempotency_key VARCHAR2(255) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE kyc_cases(id RAW(16) DEFAULT SYS_GUID() PRIMARY KEY, user_id RAW(16) NOT NULL REFERENCES users(id), status VARCHAR2(20) DEFAULT 'PENDING' NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
